        const min = Math.max(MIN_MIN_CONTENT_BOOST, Math.min(1, ...gainMin));
        const max = Math.max(MIN_MAX_CONTENT_BOOST, ...gainMax);
        this.gainMap.minContentBoost.value = min;
        this.gainMap.maxContentBoost.value = max;
        return { min, max };
